sys_script.script:
(function checkReservationIdempotency() {
    var idempotencyKey = current.getValue('idempotency_key');

    if (!idempotencyKey) {
        gs.addErrorMessage('Reservation rejected: idempotency_key is required.');
        current.setAbortAction(true);
        return;
    }

    var existing = new GlideRecord('x_1945330_retail_0_reservation');
    existing.addQuery('idempotency_key', idempotencyKey);
    existing.setLimit(1);
    existing.query();

    if (existing.hasNext()) {
        gs.addErrorMessage('Reservation rejected: idempotency_key "' + idempotencyKey + '" already exists. Duplicate reservation requests are not allowed.');
        current.setAbortAction(true);
    }
})();
